func (q *Queries) AuthoringProject(ctx context.Context, arg AuthoringProjectParams) (AuthoringProjectRow, error) {
	row := q.db.QueryRow(ctx, authoringProject, arg.WorkspaceID, arg.ID)
	var i AuthoringProjectRow
	err := row.Scan(
		&i.Name,
		&i.Slug,
		&i.Description,
		&i.Settings,
	)
	return i, err
}

const authoringReleases = `-- name: AuthoringReleases :many
SELECT id, version, note, acknowledged_seq, acknowledged_warnings, schema_version, content_hash, source_seq, counts,
    validation_report, published_by, published_at, built_at
FROM snapshot WHERE workspace_id = $1 AND project_id = $2 AND status = 'ready' ORDER BY id
`

type AuthoringReleasesParams struct {
	WorkspaceID pgtype.UUID
	ProjectID   pgtype.UUID
}

type AuthoringReleasesRow struct {
	ID                   pgtype.UUID
	Version              string
	Note                 string
	AcknowledgedSeq      int64
	AcknowledgedWarnings []byte
	SchemaVersion        pgtype.Int4
	ContentHash          pgtype.Text
	SourceSeq            pgtype.Int8
	Counts               []byte
	ValidationReport     []byte
	PublishedBy          pgtype.UUID
	PublishedAt          pgtype.Timestamptz
	BuiltAt              pgtype.Timestamptz
}

// AuthoringReleases returns the project's ready snapshots, oldest first.
func (q *Queries) AuthoringReleases(ctx context.Context, arg AuthoringReleasesParams) ([]AuthoringReleasesRow, error) {
	rows, err := q.db.Query(ctx, authoringReleases, arg.WorkspaceID, arg.ProjectID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []AuthoringReleasesRow
	for rows.Next() {
		var i AuthoringReleasesRow
		if err := rows.Scan(
			&i.ID,
			&i.Version,
			&i.Note,
			&i.AcknowledgedSeq,
			&i.AcknowledgedWarnings,
			&i.SchemaVersion,
			&i.ContentHash,
			&i.SourceSeq,
			&i.Counts,
			&i.ValidationReport,
			&i.PublishedBy,
			&i.PublishedAt,
			&i.BuiltAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

